// Uploads the 11 curriculum diagrams to Vercel Blob and attaches them as
// downloadable reference materials on the AUK SPM 020 course, each clearly
// labelled with which module it supports.
//
// Reads BLOB_READ_WRITE_TOKEN and DATABASE_URL from your .env file automatically
// (via dotenv) — no need to set them manually in this terminal session first,
// though DATABASE_URL set via `set` still overrides it if you've already set one.
//
// Run once with:  npx tsx add-course-figures.js

require("dotenv").config();
const { put } = require("@vercel/blob");
const { PrismaClient } = require("@prisma/client");
const prisma = new PrismaClient();

const figures = [
  {
    filename: "fig01.png",
    caption: "Figure 1 \u2014 Regulatory architecture behind shipboard EMS (M01)",
    b64: "",
  },
  {
    filename: "fig02.png",
    caption: "Figure 2 \u2014 Programme architecture and learner pathway",
    b64: "",
  },
  {
    filename: "fig03.png",
    caption: "Figure 3 \u2014 Machinery space oily-water flow paths (M03)",
    b64: "",
  },
  {
    filename: "fig04.png",
    caption: "Figure 4 \u2014 Bilge water discharge decision ladder (M04)",
    b64: "",
  },
  {
    filename: "fig05.png",
    caption: "Figure 5 \u2014 Sludge system boundaries: the only three lawful exits (M05)",
    b64: "",
  },
  {
    filename: "fig06.png",
    caption: "Figure 6 \u2014 Oil Record Book Part I: operation codes at a glance (M07)",
    b64: "",
  },
  {
    filename: "fig07.png",
    caption: "Figure 7 \u2014 Sewage discharge decision tree, MARPOL Annex IV (M08)",
    b64: "",
  },
  {
    filename: "fig08.png",
    caption: "Figure 8 \u2014 MARPOL Annex V garbage discharge matrix (M10)",
    b64: "",
  },
  {
    filename: "fig09.png",
    caption: "Figure 9 \u2014 Sulphur limits, changeover and fuel evidence (M12)",
    b64: "",
  },
  {
    filename: "fig10.png",
    caption: "Figure 10 \u2014 Life cycle of an environmental seal (M13)",
    b64: "",
  },
  {
    filename: "fig11.png",
    caption: "Figure 11 \u2014 Delivery model and assessment blueprint",
    b64: "",
  },
];

async function main() {
  const course = await prisma.course.findFirst({ where: { code: "AUK SPM 020" } });
  if (!course) throw new Error("Course AUK SPM 020 not found — run add-course-spm020.js first");

  const existingMaterials = Array.isArray(course.materials) ? course.materials : [];
  const newMaterials = [];

  for (const fig of figures) {
    const buffer = Buffer.from(fig.b64, "base64");
    const blob = await put(`course-figures/spm020-${fig.filename}`, buffer, {
      access: "public",
      contentType: "image/png",
      addRandomSuffix: false,
    });
    newMaterials.push({ name: fig.caption, url: blob.url });
    console.log(`  ✓ Uploaded: ${fig.caption}`);
  }

  // Merge — skip any that already exist by name (safe to re-run)
  const existingNames = new Set(existingMaterials.map((m) => m.name));
  const merged = [...existingMaterials, ...newMaterials.filter((m) => !existingNames.has(m.name))];

  await prisma.course.update({
    where: { id: course.id },
    data: { materials: merged },
  });

  console.log(`\n✓ Attached ${newMaterials.length} figures as course materials.`);
  console.log(`  Total materials on course now: ${merged.length}`);
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => prisma.$disconnect());
